/* CastConfigMapper.retrieveCategoryCnt */
SELECT COUNT(*)
FROM PMOWN.TN_PM_SMLT_FIX_ATRB_GROUP A
WHERE 1 = 1
AND A.FIX_ATRB_GROUP_ID = #{fixAtrbGroupId}

/* CastConfigMapper.retrievePsgAtrbList */ SELECT A.PSG_ATRB_CD AS ATRB_CD, A.PSG_DTL_SE_CD AS DTL_SE_CD, NVL(A.INPT_VL, ' ') AS INPT_VL, NVL(A.USER_DEF_1_VL, ' ') AS USER_DEF_1_VL, NVL(A.USER_DEF_2_VL, ' ') AS USER_DEF_2_VL, NVL(P.PSG_FIX_PARA_CD_NM, ' ') AS ATRB_CD_NM, NVL(D.PSG_FIX_PARA_CD_NM, ' ') AS DTL_SE_CD_NM, NVL(D.VL_TYPE, 'String') AS CATALOG_VL_TYPE, NVL(D.PSG_FIX_PARA_CND_TYPE_CD, ' ') AS CND_TYPE_CD, NVL(D.PSG_FIX_PARA_CND_VL, ' ') AS CND_VL, NVL(D.PRE_PRCS_YN, 'N') AS PRE_PRCS_YN FROM PMOWN.${tableNm} A JOIN PMOWN.TN_PM_SMLT_PSG_FIX_PARA_CD P ON P.PSG_FIX_PARA_CD = A.PSG_ATRB_CD JOIN PMOWN.TN_PM_SMLT_PSG_FIX_PARA_CD D ON D.PSG_FIX_PARA_CD = A.PSG_DTL_SE_CD AND D.PSG_FIX_PARA_GROUP_CD = P.PSG_FIX_PARA_CD WHERE 1 = 1 AND A.FIX_ATRB_GROUP_ID = #{fixAtrbGroupId} AND D.USE_YN = 'Y' AND SUBSTR(A.PSG_ATRB_CD, 1, 2) IN
#{rootCd}
AND ( (#{tmnlId} = 'T1' AND ( REGEXP_LIKE(P.PSG_FIX_PARA_CD_NM, '^T1([ _]|$)') OR P.PSG_FIX_PARA_CD_NM IN ('P01', 'P02') OR REGEXP_LIKE(P.PSG_SMLT_APLCN_NM, '^(P01|P02)(_|$)') )) OR (#{tmnlId} = 'T2' AND ( REGEXP_LIKE(P.PSG_FIX_PARA_CD_NM, '^T2([ _]|$)') OR P.PSG_FIX_PARA_CD_NM = 'P03' OR REGEXP_LIKE(P.PSG_SMLT_APLCN_NM, '^P03(_|$)') )) ) ORDER BY A.PSG_ATRB_CD, A.PSG_DTL_SE_CD

/* CastConfigMapper.retrieveSrvcAtrbList */ SELECT A.FCLTY_SE_CD AS ATRB_CD, A.FCLTY_DTL_CD AS DTL_SE_CD, NVL(A.INPT_VL, ' ') AS INPT_VL, NVL(A.MIN_VL, 0) AS MIN_VL, NVL(A.MAX_VL, 0) AS MAX_VL, NVL(A.DSTB_MAX_VL, 0) AS DSTB_MAX_VL, NVL(A.VL_TYPE, ' ') AS VL_TYPE, NVL(A.SWTC_FNC_ID, ' ') AS SWTC_FNC_ID, NVL(A.VRFC_FNC_ID, ' ') AS VRFC_FNC_ID, A.FCLTY_SE_CD AS ATRB_CD_NM, A.FCLTY_DTL_CD AS DTL_SE_CD_NM, 'String' AS CATALOG_VL_TYPE, 'N' AS PRE_PRCS_YN FROM PMOWN.TN_PM_SMLT_SRVC_ATRB A WHERE 1 = 1 AND A.FIX_ATRB_GROUP_ID = #{fixAtrbGroupId} AND A.FCLTY_SE_CD IN
#{fcltySeCd}
ORDER BY A.FCLTY_SE_CD, A.FCLTY_DTL_CD

mapper.update:
/* CastConfigMapper.updateAtrbValue */

UPDATE PMOWN.${tableNm}
SET ${columnNm} = #{value},
    LAST_MDFR_ID = #{loginUserId},
    LAST_MDFR_IP_ADDR = #{loginIpAddr},
    LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE 1 = 1
AND ${groupColumnNm} = #{fixAtrbGroupId}
AND ${keyColumnNm} = #{keyCd}

AND ${dtlColumnNm} = #{dtlSeCd}

/* CastConfigMapper.copyFromGroup */
UPDATE PMOWN.${tableNm} A
SET

    A.${columnNm} = (
        SELECT B.${columnNm}
        FROM PMOWN.${tableNm} B
        WHERE B.${groupColumnNm} = #{srcFixAtrbGroupId}
        AND B.${keyColumnNm} = A.${keyColumnNm}

        AND B.${dtlColumnNm} = A.${dtlColumnNm}

    )
,
    A.LAST_MDFR_ID = #{loginUserId},
    A.LAST_MDFR_IP_ADDR = #{loginIpAddr},
    A.LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE 1 = 1
AND A.${groupColumnNm} = #{fixAtrbGroupId}
AND A.${keyColumnNm} = #{keyCd}

AND A.${dtlColumnNm} = #{dtlSeCd}

AND EXISTS (
    SELECT 1
    FROM PMOWN.${tableNm} B
    WHERE B.${groupColumnNm} = #{srcFixAtrbGroupId}
    AND B.${keyColumnNm} = A.${keyColumnNm}

    AND B.${dtlColumnNm} = A.${dtlColumnNm}

)

mapper.insert:
/* CastConfigMapper.insertAplyHstryDtl */

INSERT INTO PMOWN.TN_PM_SMLT_ATRB_APLY_HSTRY_DTL (
    APLY_SN, ATRB_CD, DTL_SE_CD, COLUMN_NM, BEF_VL, AFT_VL
)

    SELECT
        #{aplySn},
        #{keyCd},
        #{dtlSeCd},
        #{columnNm},
        TO_CHAR(T.${columnNm}),
        TO_CHAR(S.${columnNm})
    FROM PMOWN.${tableNm} T, PMOWN.${tableNm} S
    WHERE T.${groupColumnNm} = #{tgtFixAtrbGroupId}
    AND T.${keyColumnNm} = #{keyCd}

    AND T.${dtlColumnNm} = #{dtlSeCd}

    AND S.${groupColumnNm} = #{srcFixAtrbGroupId}
    AND S.${keyColumnNm} = #{keyCd}

    AND S.${dtlColumnNm} = #{dtlSeCd}

mapper.select:
/* CastConfigMapper.retrieveAplyHstryList */ SELECT A.APLY_SN AS APLY_SN, A.SRC_FIX_ATRB_GROUP_ID AS SRC_FIX_ATRB_GROUP_ID, A.TGT_FIX_ATRB_GROUP_ID AS TGT_FIX_ATRB_GROUP_ID, NVL(A.TMNL_ID, ' ') AS TMNL_ID, NVL(A.TBL_NM, ' ') AS TBL_NM, NVL(A.SHEET_NM, ' ') AS SHEET_NM, NVL(A.APLY_ROW_CNT, 0) AS APLY_ROW_CNT, NVL(A.CNCL_YN, 'N') AS CNCL_YN, CASE WHEN NVL(A.CNCL_YN, 'N') = 'N' AND NOT EXISTS ( SELECT 1 FROM PMOWN.TN_PM_SMLT_ATRB_APLY_HSTRY N WHERE N.TGT_FIX_ATRB_GROUP_ID = A.TGT_FIX_ATRB_GROUP_ID AND NVL(N.TMNL_ID, ' ') = NVL(A.TMNL_ID, ' ') AND N.TBL_NM = A.TBL_NM AND NVL(N.CNCL_YN, 'N') = 'N' AND N.APLY_SN > A.APLY_SN ) THEN 'Y' ELSE 'N' END AS REVERTABLE_YN, NVL(TO_CHAR(A.FRST_REG_DT, 'YYYYMMDDHH24MISS'), ' ') AS FRST_REG_DT, NVL(A.FRST_RGTR_ID, ' ') AS FRST_RGTR_ID FROM PMOWN.TN_PM_SMLT_ATRB_APLY_HSTRY A WHERE 1 = 1 AND A.TGT_FIX_ATRB_GROUP_ID = #{tgtFixAtrbGroupId}
AND A.TMNL_ID = #{tmnlId}
AND A.SHEET_NM = #{sheetNm}
ORDER BY A.APLY_SN DESC
